                                                State<LudoHome> createState() => _LudoHomeState();
                                                }

                                                class _LudoHomeState extends State<LudoHome> {
                                                  int dice = 1;
                                                    String currentPlayer = 'Red';

                                                      void rollDice() {
                                                          setState(() {
                                                                dice = DateTime.now().millisecondsSinceEpoch % 6 + 1;
                                                                    });
                                                                      }

                                                                        @override
